  VIEWS.crmstat = () => { const tb = UI.crmST || 'day'; return head('학원 현황', '오늘과 이번 달을 숫자로 봅니다', setBtn()) + sampleBar() + tabs('crmST', [['day', '일일 현황'], ['mon', '월별 현황'], ['tch', '강사별']], tb) + (tb === 'mon' ? statMon() : tb === 'tch' ? statTch() : statDay()); };
  function statDay() { const d = curD(); const F = dailyFacts(d); return `<div class="bar2"><input type="date" value="${esc(d)}" aria-label="기준일" data-chg="crm-sd"></div><div class="card k-sum">${dailySummary(d, F).map(x => `<p class="k-p">${esc(x)}</p>`).join('')}</div><section class="grid g4">${kpi('출결 입력', `${F.marked}/${F.need}`)}${kpi('결석', F.absent + '명', '', F.absent ? 'r' : '')}${kpi('수납', won(F.income))}${kpi('미납 잔액', won(F.un), '', F.un ? 'r' : '')}</section>${S.me.role === 'teacher' ? '' : `<div class="card"><div class="ch"><b>자동 운영</b><small>${d === today() ? `오늘 ${runToday().reduce((a, x) => a + x.n, 0)}건 처리` : ''}</small><button class="btn sm" data-act="crm-set">설정</button></div>${autoListHTML()}</div>`}`; }
