  function statTch() { const ym = UI.crmTM || today().slice(0, 7); const names = [...new Set((S.classes || []).filter(c => c.status !== '종료').map(c => c.teacher || '미지정'))]; const P = allPays(); return `<div class="bar2"><label class="mini">기준 월 <input type="month" value="${esc(ym)}" data-chg="crm-tm"></label></div><div class="card">${table(['강사', '수업', '재원생', '출석률', '청구', '수납', '미납', '상담'], names.map(n => { const L = (S.classes || []).filter(c => c.status !== '종료' && (c.teacher || '미지정') === n); const ids = new Set(L.flatMap(c => rollOf(c).map(m => m.id))); let ok = 0, tot = 0; L.filter(W2.hasUnits).forEach(c => W2.units(c).filter(u => monthOf(u.date) === ym).forEach(u => rollOf(c).forEach(m => { const v = W2.get(c, u.id, m.id); if (v) { tot++; if (v !== '결석') ok++; } }))); const cid = new Set(L.map(c => c.id)); const B = (S.bills || []).filter(b => b.status !== '취소' && cid.has(b.cls) && b.month === ym); const Pm = P.filter(p => cid.has(p.b.cls) && monthOf(p.at) === ym); return [esc(n), L.length + '개', ids.size + '명', tot ? Math.round(ok / tot * 100) + '%' : '—', won(B.reduce((a, b) => a + billTotal(b), 0)), won(Pm.reduce((a, p) => a + p.amt, 0)), won(B.reduce((a, b) => a + billBal(b), 0)), (S.consults || []).filter(c => c.staff === n && monthOf(c.at) === ym).length + '건']; }), '운영 중인 수업이 없습니다.')}</div>`; }
