  const bare = s => String(s || '').replace('[샘플] ', '').replace(/\s+/g, '');
  const whoIn = q => { const Q = bare(q); return STUDENTS().filter(m => bare(m.name).length >= 2 && Q.includes(bare(m.name))); };
  const clsIn = q => { const Q = bare(q); return myCls().filter(c => bare(c.name).length >= 2 && Q.includes(bare(c.name))); };
  const dateIn = q => /내일/.test(q) ? addDays(today(), 1) : /모레/.test(q) ? addDays(today(), 2) : /오늘/.test(q) ? today() : (typeof scxParse === 'function' && scxParse(q).date) || '';
