    if (!tch && /자동/.test(s) && /(발생|청구)/.test(s) && /(켜|꺼|끄|설정)/.test(s)) { if (!owner) return scxInfo('수납 설정은 정운영자만 바꿉니다.'); const on = !/(꺼|끄)/.test(s); return scxPlan(`정기 납부일 자동 발생 ${on ? '켜기' : '끄기'}`, on ? '정기 납부일이 지난 재원생 수강료를 수납 화면을 열 때 자동으로 만듭니다.' : '자동 발생을 끕니다.', () => { CFG().autoBill = on; CFG().auto.bill = on; if (on) CFG().auto.billFrom = ''; logAudit('수납 설정 변경'); return `자동 발생을 ${on ? '켰습니다' : '껐습니다'}.`; }); }
