    if (!tch && /미납/.test(s)) { if (!owner) return scxInfo('수납은 정운영자만 볼 수 있습니다.'); const L = (S.bills || []).filter(billOpen); return scxInfo(`미납 ${L.length}건입니다.`, nameTable(['원생', '청구', '잔액'], L.slice(0, 30).map(b => [esc(billWho(b).map(id => (M(id) || {}).name || '').join(', ')), esc(b.title), won(billBal(b))]), '미납이 없습니다.')); }
    if (!tch && /(수납|납부|냈|입금|결제)/.test(s) && amtIn(s) > 0 && whoIn(s).length) { if (!owner) return scxInfo('수납은 정운영자만 처리합니다.'); const W = whoIn(s); const e = pick1(W, '원생'); if (e) return e; const m = W[0]; const b = (S.bills || []).filter(x => billOpen(x) && billWho(x).includes(m.id)).sort((a, x) => String(a.due) < String(x.due) ? -1 : 1)[0]; if (!b) return scxInfo('이 원생의 미납 청구가 없습니다.'); const a = amtIn(s), bal = billBal(b); if (a > bal) return scxInfo(`잔액 ${won(bal)}보다 큰 금액입니다.`); const me = /카드/.test(s) ? '카드' : /(계좌|이체)/.test(s) ? '계좌이체' : '현금'; return scxPlan('수납 처리', `가장 오래된 청구에 ${won(a)}을(를) ${me}${me === '현금' ? '으로' : '로'} 수납합니다.`, () => { b.paid = Array.isArray(b.paid) ? b.paid : []; b.paid.push({ id: uid('pd'), at: today(), amt: a, method: me, memo: 'AI SAM', by: S.me.name }); b.status = billBal(b) > 0 ? '부분 납부' : '납부 완료'; b.payAt = today(); logAudit(`AI SAM 수납 — ${won(a)}`); return '수납 처리했습니다.'; }, { html: nameTable(['원생', '청구', '잔액'], [[esc(m.name), esc(b.title), won(bal)]]) }); }
    /* 원생 이동 */
    if (!tch && /(전반|반\s*이동|반을?\s*옮|으로\s*옮)/.test(s)) { const W = whoIn(s); const e = pick1(W, '원생'); if (e) return e; const m = W[0]; const CC = clsIn(s); const cur = clsOf(m.id); const to = CC.find(c => !c.learners.includes(m.id)); const from = CC.find(c => c.learners.includes(m.id)) || (cur.length === 1 ? cur[0] : null); if (!to || !from) return scxInfo('옮길 수업을 찾지 못했습니다. 「○○를 ○○반으로 전반」처럼 수업 이름을 말씀해 주십시오.'); return scxPlan('전반', `원생 1명을 다른 수업으로 옮깁니다.`, () => { moveOne(m.id, from, to); logAudit(`AI SAM 전반 — ${m.sid}`); return '전반했습니다.'; }, { html: nameTable(['원생', '기존', '새 수업'], [[esc(m.name), esc(from.name), esc(to.name)]]) }); }
    if (!tch && /(휴원|퇴원|복귀|재원\s*처리)/.test(s) && whoIn(s).length) { const W = whoIn(s); const act = /퇴원/.test(s) ? '퇴원' : /휴원/.test(s) ? '휴원' : '재원'; const e = pick1(W, '원생'); if (e) return e; const m = W[0]; const rs = (s.match(/(?:사유|이유)[는은:\s]*([^,.]+)/) || [])[1] || ''; if (act === '퇴원' && !rs) return scxInfo('퇴원 사유를 함께 말씀해 주십시오. 예: 「○○ 퇴원, 사유 이사」'); return scxPlan(`${act} 처리`, `원생 1명을 ${act} 처리합니다.${act === '퇴원' ? ' 수업에서 빠지고 이후 수강료를 만들지 않습니다.' : ''}`, () => { setStatus([m.id], act, today(), rs.trim()); logAudit(`AI SAM ${act} — ${m.sid}`); return `${act} 처리했습니다.`; }, { html: nameTable(['원생', '사유'], [[esc(m.name), esc(rs.trim() || '—')]]) }); }
    /* 출결 */
    if (/(전체|모두|다)\s*출석/.test(s)) { const d = today(); const CC = clsIn(s); const U = dayUnits(d).filter(x => !dxRead(x.c, x.u.id).closed && (!CC.length || CC.includes(x.c))); let n = 0; U.forEach(({ c, u }) => { n += rollOf(c).filter(m => !W2.get(c, u.id, m.id)).length; }); if (!n) return scxInfo('출석 처리할 미입력 원생이 없습니다.'); return scxPlan('미입력 전체 출석', `오늘 수업 ${U.length}개의 미입력 ${n}명을 출석 처리합니다.`, () => { U.forEach(({ c, u }) => rollOf(c).forEach(m => { if (!W2.get(c, u.id, m.id)) W2.set(c, u.id, m.id, '출석'); })); logAudit(`AI SAM 일괄 출석 — ${n}명`); return `${n}명을 출석 처리했습니다.`; }, { go: 'crmatt' }); }
    if (/휴강/.test(s)) { const CC = clsIn(s); const e = pick1(CC, '수업'); if (e) return e; const c = CC[0]; const d = dateIn(s) || today(); const u = W2.units(c).find(x => x.date === d); if (!u) return scxInfo(`${d}에 「${c.name}」 수업이 없습니다.`); return scxPlan('휴강 처리', `${d} 「${c.name}」 수업을 휴강 처리합니다. 출석률에서 제외합니다.`, () => { ACT['crm-att-close']({ dataset: { c: c.id, k: u.id } }); return '휴강 처리했습니다.'; }, { go: 'crmatt' }); }
    if (/보강/.test(s) && !tch && whoIn(s).length) { const W = whoIn(s); const e = pick1(W, '원생'); if (e) return e; const m = W[0]; const CC = clsIn(s); const c = CC[0] || clsOf(m.id)[0]; const d = dateIn(s); if (!c) return scxInfo('수강 중인 수업을 찾지 못했습니다.'); if (!d) return scxInfo('보강 날짜를 함께 말씀해 주십시오. 예: 「○○ 11월 20일 보강」'); return scxPlan('보강 등록', `${d} 보강을 등록합니다.`, () => { (c.makeups = c.makeups || []).push({ id: uid('mk'), mid: m.id, from: '', date: d, time: '', memo: 'AI SAM', st: '예정' }); W2.notify([m.id], '보강 안내', `[${S.org.name}] 「${c.name}」 보강이 ${d}에 예정되었습니다.`); logAudit('AI SAM 보강 등록'); return '보강을 등록했습니다.'; }, { html: nameTable(['원생', '수업', '일자'], [[esc(m.name), esc(c.name), esc(d)]]) }); }
    if (/결석/.test(s)) { const d = dateIn(s) || today(); const rows = []; dayUnits(d).forEach(({ c, u }) => rollOf(c).forEach(m => { if (W2.get(c, u.id, m.id) === '결석') rows.push([esc(m.name), esc(c.name)]); })); return scxInfo(`${d} 결석 ${rows.length}명입니다.`, nameTable(['원생', '수업'], rows, '결석한 원생이 없습니다.')); }
