    if (/성적\s*(알림|안내)|(점수|성적).*(보내|알려\s*줘|발송)/.test(s) && !whoIn(s).length) { if (tch) return scxInfo('성적 알림은 운영자 화면에서 등록합니다.'); const CC = clsIn(s); const L = (CC.length ? CC : myCls()).flatMap(c => (c.k12Exams || []).filter(e => !e.sent && Object.values(e.scores || {}).some(x => x.v != null)).map(e => ({ c, e }))).sort((a, b) => a.e.date < b.e.date ? 1 : -1); if (!L.length) return scxInfo('알림을 등록할 시험이 없습니다.'); const { c, e } = L[0]; const ids = Object.keys(e.scores).filter(id => M(id) && e.scores[id].v != null && !e.scores[id].absent); const A = rankOf(e).avg; return scxPlan('성적 알림 등록', `「${c.name}」 ${e.name} ${ids.length}명의 알림을 등록합니다. 석차는 넣지 않습니다.`, () => { W2.notify(ids, '성적 알림', m => `[${S.org.name}] ${m.name} ${t('learner')}의 「${c.name}」 ${e.name} 점수는 ${e.scores[m.id].v}점(만점 ${e.max}, 반 평균 ${A})입니다.`); e.sent = today(); logAudit(`성적 알림 — ${ids.length}명`); return `${ids.length}명을 등록했습니다.`; }); }
